(--border);padding:0 42px;display:flex;justify-content:space-between;align-items:center;background:var(--surface);font-size:12px;color:var(--muted)}.topbar b{margin:0 13px;color:#c7d3d8;font-weight:400}.theme-button{border:1px solid var(--border);background:var(--surface);color:var(--ink);width:35px;height:35px;border-radius:50%;font-size:21px}main{max-width:1450px;margin:auto;padding:37px 42px 20px}.page-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.eyebrow{font-size:9px;letter-spacing:1.8px;color:var(--muted);margin:0 0 10px;font-weight:650}h1{font-size:27px;letter-spacing:.4px;margin:0 0 10px;font-weight:680}.description{font-size:12px;color:var(--muted);margin:0}.refresh{display:flex;gap:8px;align-items:center;border:1px solid var(--border);border-radius:7px;padding:10px 14px;background:var(--surface);color:var(--ink);font-size:11px}.refresh span{font-size:19px}.status-line{display:flex;justify-content:space-between;gap:14px;font-size:10px;color:var(--muted);margin:29px 0 18px}.status-line>span:first-child{color:var(--accent)}.status-line small{margin-left:14px;color:var(--muted);font-size:10px}.devices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-bottom:25px}.device-card,.card{background:var(--surface);border:1px solid var(--border);border-radius:12px}.device-card{padding:21px 22px 14px;border-top:3px solid var(--device-color)}.device-heading{display:flex;align-items:center;gap:9px}.device-icon{display:flex;align-items:center;justify-content:center;background:var(--bg);color:var(--device-color);width:32px;height:32px;border-radius:8px;font-size:23px}.device-heading h2{font-size:13px;font-weight:650;margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.device-badge{margin-left:auto;background:var(--accent-soft);color:var(--accent);border-radius:4px;padding:4px 6px;font-size:9px;white-space:nowrap}.device-badge.stale{background:#fff1da;color:#a47422}.temperature{font-size:43px;letter-sp