px;color:var(--muted)}.spinning{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(min-width:1600px){main{padding-top:50px}}@media(max-width:1150px){.sidebar{width:190px;padding:30px 16px}.workspace{margin-left:190px}main{padding:28px 24px}.topbar{padding:0 24px}.device-card{padding:17px 15px}.device-badge{font-size:8px}.device-heading{gap:5px}.devices{gap:12px}.status-line small{display:none}}@media(max-width:850px){.sidebar{position:static;width:auto;flex-direction:row;padding:14px 20px;border-right:0;border-bottom:1px solid var(--border);align-items:center;gap:20px}.brand{font-size:12px}.brand-mark{width:32px;height:35px;font-size:24px}.brand-mark span{font-size:15px;margin-top:-12px}.nav-heading,.sidebar-bottom{display:none}nav{display:flex;gap:5px;margin-left:auto}nav button,nav a{font-size:10px;padding:9px}nav span{display:none}.workspace{margin-left:0}.topbar{height:52px}.devices{gap:12px}.device-icon{display:none}.temperature{font-size:36px}.device-badge{margin-left:auto}.device-heading h2{font-size:12px}.status-line{font-size:9px}}@media(max-width:600px){.sidebar{padding:13px 14px;gap:7px}.brand{gap:7px;font-size:10px}nav{gap:1px}nav button,nav a{padding:9px 7px;font-size:9px}.topbar{padding:0 18px;font-size:10px}main{padding:25px 16px 10px}h1{font-size:22px}.eyebrow{font-size:8px}.description{font-size:10px}.refresh{font-size:9px;padding:7px 9px;white-space:nowrap}.page-heading{gap:8px}.status-line{flex-wrap:wrap;gap:8px;margin:22px 0 14px}.devices{grid-template-columns:1fr}.device-card{padding:18px 20px 14px}.device-icon{display:flex}.device-heading h2{font-size:14px}.temperature{font-size:42px;margin:14px 0}.secondary-values{padding-bottom:12px}.device-footer{font-size:10px}.motion{font-size:10px}.chart-panel{padding:20px 14px 14px}.panel-heading{align-items:flex-start}.periods button{padding:6px 8px;font-size:9px}.panel-heading h2{font-size:14px}.chart-toolbar{margin-top:23px}.metric-tabs{gap:14px}.metric-tabs button{font-size:11px}.average{font-size:9px}.average strong{font-size:16px;margin-left:5px}.legend{gap:12px}.chart-empty{height:250px}.table-panel .panel-heading{padding:20px 16px}th,td{padding:13px 16px}footer{font-size:8px;gap:10px;flex-wrap:wrap}.notice{font-size:11px}}
</style>
